sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// Add your code here
	// gs.info("SV PDI: STARTING");
	var kb = new GlideRecord('kb_knowledge');
	kb.addQuery('article_id', '00cd08eb97ff4710d3efb73de053af4e'); //00cd08eb97ff4710d3efb73de053af4e
	kb.addQuery('workflow_state', 'published');
	kb.orderByDesc('version');
	kb.setLimit(1);
	kb.query();

	if (kb.next()) {
		//Check out the article;
		// gs.info("SV PDI: CHECKING OUT");
		// TODO Move the messages to messages table
		var recordClass = kb.sys_class_name;
		var previous_valid_to = kb.getDisplayValue("valid_to");
		var newRecord = new global.KBVersioning().checkout(kb);

		if (newRecord) {
			if (recordClass == 'kb_knowledge_block')
				gs.addInfoMessage(gs.getMessage("A new version of the block is created for revision."));
			else
				gs.addInfoMessage(gs.getMessage("A new version of the article is created for revision."));

			var current_valid_to = newRecord.getDisplayValue("valid_to");
			if (previous_valid_to != current_valid_to) {
				if (gs.nil(previous_valid_to))
					gs.addInfoMessage(gs.getMessage("Valid to has been changed to {0}.", current_valid_to));
				else
					gs.addInfoMessage(gs.getMessage("Valid to has been changed from {0} to {1}.", [previous_valid_to, current_valid_to]));
			}

			//Update and publish newRecord
			// gs.info("SV PDI: UPDATING");
			var updatedText = "<p>This article has been automatically updated through a Business Rule on the Page Route Map table.</p><p>&nbsp;</p>";

			var prm = new GlideRecord(current.getTableName());
			prm.addEncodedQuery("active=true^portalsLIKEebcd3cdb97ab8fd0d3efb73de053af30");
			prm.orderBy('route_from_page');
			prm.orderBy('route_to_page');
			prm.query();

			if (!prm.hasNext()) {
				updatedText += "<p>There are no active Page Route Map entries for the SV Public Demo Portal.</p>";
			} else {
				updatedText += '<h4 style="width: max-content; max-width: 100%">Active Page Route Maps on the SV Public Demo Portal</h4>';
				updatedText += '<table><tr><th style="width: 50%;">Route From</th><th style="width: 50%;">Route To</th></tr>';
				while (prm.next()) {
					updatedText += "<tr><td>" + prm.route_from_page.id + "</td><td>" + prm.route_to_page.id + "</td></tr>";
				}
				updatedText += "</table>";
			}

			newRecord.text = updatedText;
			newRecord.update();

			// gs.info("SV PDI: PUBLISHING");
			publish(newRecord);
		} else {
			gs.addErrorMessage(gs.getMessage("You cannot checkout this article as it is already checked out."));
		}
	}

	function publish(articleGr) {
		var getArt = new GlideRecord('kb_knowledge');
		getArt.get(articleGr.sys_id.toString());
		new global.KnowledgeUIAction().publish(getArt);
		gs.addInfoMessage('New version of <a href="/kb_knowledge.do?sys_id=' + getArt.sys_id.toString() + '" target="_blank">' + getArt.number + '</a> created.');
	}

})(current, previous);
